<?php
require_once __DIR__ . '/../core/auth.php';
require_once __DIR__ . '/../core/csrf.php';
require_once __DIR__ . '/../core/security.php';
require_once __DIR__ . '/../core/permissions.php';
require_once __DIR__ . '/../core/api_pairing.php';
start_secure_session(); require_admin(); ensure_hope_integration_schema();
if(!current_user_is_owner()){ http_response_code(403); die('Akses ditolak.'); }
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){ csrf_check(); if(($_POST['act']??'')==='clear_old'){ db()->exec("DELETE FROM api_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL 30 DAY)"); set_setting('last_integration_error','Log lama >30 hari dibersihkan.'); redirect(base_url('admin/api_error_log.php')); } }
$scope=$_GET['scope']??'error'; $endpoint=trim((string)($_GET['endpoint']??'')); $where=[]; $params=[];
if($scope!=='all') $where[]="(LOWER(status) LIKE '%fail%' OR LOWER(status) LIKE '%error%' OR LOWER(status) LIKE '%invalid%' OR LOWER(status) LIKE '%reject%' OR LOWER(status) LIKE '%revoked%')";
if($endpoint!==''){ $where[]='endpoint LIKE ?'; $params[]='%'.$endpoint.'%'; }
$sql='SELECT * FROM api_logs'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC LIMIT 250'; $st=db()->prepare($sql); $st->execute($params); $rows=$st->fetchAll(PDO::FETCH_ASSOC);
$tests=db()->query('SELECT * FROM api_connection_test_logs ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
$customCss=setting('custom_css',''); function badge_api($s){ $s=(string)$s; $cls=(stripos($s,'ok')!==false||stripos($s,'success')!==false)?'ok':((stripos($s,'pending')!==false)?'warn':'danger'); return '<span class="badge '.$cls.'">'.e($s).'</span>'; }
function clip_api($v,$len=1800){ $t=trim((string)$v); return strlen($t)>$len?substr($t,0,$len).'...':$t; }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Error Log API</title><link rel="icon" href="<?php echo e(favicon_url()); ?>"><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?>.compact-admin{font-size:13px}.compact-admin .table th,.compact-admin .table td{padding:7px 8px;vertical-align:top}.log-pre{white-space:pre-wrap;max-width:860px;max-height:260px;overflow:auto;font-size:12px;background:#0f172a;color:#e5e7eb;padding:10px;border-radius:10px}.filter-row{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.filter-row input,.filter-row select{min-height:34px;padding:6px 8px;font-size:13px}</style></head><body><div class="container"><?php include __DIR__.'/partials_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" data-toggle-sidebar type="button">Menu</button><div class="title">Error Log API</div><div class="spacer"></div><a class="btn" href="<?php echo e(base_url('admin/dapur_connection.php')); ?>">Koneksi ke Dapur</a></div><div class="content compact-admin"><div class="card"><h3>Error Log HOPe</h3><p class="muted">Menangkap error pairing, test koneksi, dry-run transfer, token, permission, HTTP error, dan SQL/exception integrasi.</p><form method="get" class="filter-row"><div><label>Tampilan</label><select name="scope"><option value="error" <?php echo $scope==='error'?'selected':''; ?>>Error saja</option><option value="all" <?php echo $scope==='all'?'selected':''; ?>>Semua log</option></select></div><div><label>Endpoint</label><input name="endpoint" value="<?php echo e($endpoint); ?>" placeholder="api/pairing"></div><button class="btn light">Filter</button></form></div><div class="card"><h3>Log Operasional</h3><table class="table"><tr><th>Waktu</th><th>Arah</th><th>Endpoint</th><th>Status</th><th>Pesan</th><th>Payload/Response</th></tr><?php foreach($rows as $r): ?><tr><td><?php echo e($r['created_at']); ?></td><td><?php echo e($r['direction']); ?></td><td><?php echo e($r['endpoint']); ?></td><td><?php echo badge_api($r['status']); ?></td><td><?php echo e($r['message']); ?></td><td><?php $p=trim((string)($r['payload_json']??'')); echo $p!==''?'<details><summary>Lihat</summary><pre class="log-pre">'.e(clip_api($p)).'</pre></details>':'-'; ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="muted">Tidak ada log sesuai filter.</td></tr><?php endif; ?></table></div><div class="card"><h3>Log Test Koneksi</h3><table class="table"><tr><th>Waktu</th><th>Target</th><th>Endpoint</th><th>HTTP</th><th>Status</th><th>Pesan</th><th>Response</th></tr><?php foreach($tests as $t): ?><tr><td><?php echo e($t['created_at']); ?></td><td><?php echo e($t['target_base_url']); ?></td><td><?php echo e($t['endpoint']); ?></td><td><?php echo e((string)$t['http_status']); ?></td><td><?php echo badge_api($t['status']); ?></td><td><?php echo e($t['message']); ?></td><td><?php $p=trim((string)($t['response_body']??'')); echo $p!==''?'<details><summary>Lihat</summary><pre class="log-pre">'.e(clip_api($p)).'</pre></details>':'-'; ?></td></tr><?php endforeach; if(!$tests): ?><tr><td colspan="7" class="muted">Belum ada test koneksi.</td></tr><?php endif; ?></table></div><form method="post" onsubmit="return confirm('Hapus log lebih dari 30 hari?')"><input type="hidden" name="_csrf" value="<?php echo e(csrf_token()); ?>"><input type="hidden" name="act" value="clear_old"><button class="btn danger">Bersihkan Log Lama &gt; 30 Hari</button></form></div></div></div><script defer src="<?php echo e(asset_url('assets/app.js')); ?>"></script></body></html>
